import sys,zipfile,pathlib,json,hashlib,stat,os
archive,dest=sys.argv[1:]; dest=pathlib.Path(dest).resolve(); dest=pathlib.Path(chr(92)*2+'?'+chr(92)+str(dest)) if os.name=='nt' else dest
with open(archive,'rb') as f:
 h=hashlib.file_digest(f,'sha256').hexdigest()
if h!='01da25bb19bf1a8dbf9a58eff6a94055ba81bff1b3ccac32b6cf001e37201e75':raise ValueError('archive SHA mismatch')
with zipfile.ZipFile(archive) as z:
 b=z.read('engine/SOURCE.json')
 if hashlib.sha256(b).hexdigest()!='58fb690081f06fc3851266340f16927b44ab2c84ef236cdc4dad37761b247be0':raise ValueError('SOURCE SHA mismatch')
 s=json.loads(b); contract={**s['files'],**s.get('distributionFiles',{})}; expected=set(contract)|{'SOURCE.json'}
 entries=[i for i in z.infolist() if i.filename.startswith('engine/') and not i.is_dir()]
 if len(entries)!=len(expected) or {i.filename[7:] for i in entries}!=expected:raise ValueError('complete ZIP coverage mismatch')
 for i in entries:
  rel=i.filename[7:]; parts=pathlib.PurePosixPath(rel)
  if parts.is_absolute() or '..' in parts.parts or ':' in rel or '\\' in rel or stat.S_ISLNK(i.external_attr>>16):raise ValueError('unsafe ZIP entry')
  data=z.read(i)
  if rel!='SOURCE.json' and (hashlib.sha256(data).hexdigest()!=contract[rel]['sha256'] or len(data)!=contract[rel]['size']):raise ValueError('content mismatch '+rel)
  out=dest.joinpath(*parts.parts);out.parent.mkdir(parents=True,exist_ok=True)
  with out.open('xb') as f:f.write(data)
 print(json.dumps({'archiveSha256':h,'engineEntries':len(entries),'receiptFiles':len(s['files']),'engineBytes':sum(i.file_size for i in entries)}))
